      "signatureWeaponId": "23060",
      "signatureWeaponName": "A Star That Lights the Night",
      "overviewArt": "../../Database/Nanoka/hsr/assets/lightcones/full/23060.webp",
      "overviewArtPool": [
        "../../Database/Nanoka/hsr/assets/lightcones/full/23060.webp"
      ],
      "status": "beta",
